
-- Personal Vehicles Shadow Migration
-- Phase 8: Shadow Columns & Backfill

BEGIN;

-- 1. Add Shadow Columns to 'personal_vehicles'
ALTER TABLE public.personal_vehicles 
ADD COLUMN IF NOT EXISTS id_uuid UUID DEFAULT gen_random_uuid(),
ADD COLUMN IF NOT EXISTS legacy_id TEXT;

-- 2. Backfill 'personal_vehicles'
-- Logic:
--   - If 'id' looks like UUID, use it as 'id_uuid'
--   - If 'id' is legacy, 'id_uuid' is already auto-generated by DEFAULT (or we can explicit set it if needed, but default is safer for unique)
--   - 'legacy_id' always stores the original 'id'
UPDATE public.personal_vehicles
SET 
  legacy_id = id,
  id_uuid = CASE 
    WHEN id ~* '^[0-9a-f-]{36}$' THEN id::uuid 
    ELSE id_uuid -- Keep the default generated one
  END;

-- 3. Enforce Unique/Not Null on Shadow PK
ALTER TABLE public.personal_vehicles ALTER COLUMN id_uuid SET NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_personal_vehicles_id_uuid ON public.personal_vehicles(id_uuid);
ALTER TABLE public.personal_vehicles ADD CONSTRAINT personal_vehicles_id_uuid_unique UNIQUE USING INDEX idx_personal_vehicles_id_uuid;


-- 4. Add Shadow Column to 'vehicle_attendance'
ALTER TABLE public.vehicle_attendance 
ADD COLUMN IF NOT EXISTS vehicle_id_uuid UUID;

-- 5. Backfill 'vehicle_attendance'
-- Join on the TEXT id to find the new UUID
UPDATE public.vehicle_attendance va
SET vehicle_id_uuid = pv.id_uuid
FROM public.personal_vehicles pv
WHERE va.vehicle_id = pv.id;

-- 6. Add Foreign Key Constraint (Shadow)
-- We check for orphans first? strict constraint might fail if orphans exist.
-- Let's try adding it. If it fails, user will report orphans.
ALTER TABLE public.vehicle_attendance
ADD CONSTRAINT fk_vehicle_attendance_uuid
FOREIGN KEY (vehicle_id_uuid)
REFERENCES public.personal_vehicles(id_uuid);

COMMIT;
